import"./app.min.js";document.addEventListener("DOMContentLoaded",function(){document.querySelectorAll(".video-container").forEach(o=>{const t=o.querySelector(".video-preview"),e=o.querySelector("video");t.addEventListener("click",function(){o.classList.add("playing"),e.play().catch(n=>{console.log("\u041E\u0448\u0438\u0431\u043A\u0430 \u0432\u043E\u0441\u043F\u0440\u043E\u0438\u0437\u0432\u0435\u0434\u0435\u043D\u0438\u044F:",n)})}),e.addEventListener("click",function(n){n.stopPropagation(),e.paused?e.play():e.pause()}),e.addEventListener("ended",function(){o.classList.remove("playing")})})});
